function first(value) {
  return Array.isArray(value) ? value[0] : value;
}

function parseHikeParams(params) {
  const rawId = first(params.id);
  const id = /^\d+$/.test(rawId ?? '') && Number(rawId) > 0 ? Number(rawId) : null;

  const rawUnits = String(first(params.units) ?? '').toLowerCase();
  const units = rawUnits === 'mi' ? 'mi' : 'km';

  const rawPhoto = first(params.photo);
  const photo = /^\d+$/.test(rawPhoto ?? '') ? Number(rawPhoto) : 0;

  return { id, units, photo };
}

console.log(parseHikeParams({ id: '42', units: 'MI', photo: '2' }));
console.log(parseHikeParams({ id: 'abc' }));
